import os, json
from core.app_paths import APP_ROOT, USER_STATE_DIR

# cache path
_CACHE_DIR = USER_STATE_DIR
_LANG_FILE = os.path.join(_CACHE_DIR, "lang.json")
_LEGACY_LANG_FILE = os.path.join(APP_ROOT, "cache", "user", "lang.json")

SUPPORTED = {
    "en": "English",
    "id": "Indonesia",
    "zh": "中文",
    "ru": "Русский",
    "hi": "हिन्दी",
    "pt": "Português",
    "vi": "Tiếng Việt",
    "tr": "Türkçe",
    "ja": "日本語",
}
DEFAULT_LANG = "en"


def _migrate_legacy_lang():

    if os.path.isfile(_LANG_FILE) or not os.path.isfile(_LEGACY_LANG_FILE):
        return
    try:
        os.makedirs(_CACHE_DIR, exist_ok=True)
        os.replace(_LEGACY_LANG_FILE, _LANG_FILE)
    except OSError:
        pass


def load_lang() -> str:
    _migrate_legacy_lang()
    try:
        with open(_LANG_FILE, "r") as f:
            code = json.load(f).get("lang", DEFAULT_LANG)
        return code if code in SUPPORTED else DEFAULT_LANG
    except Exception:
        return DEFAULT_LANG


def save_lang(code: str):
    _migrate_legacy_lang()
    os.makedirs(_CACHE_DIR, exist_ok=True)
    with open(_LANG_FILE, "w") as f:
        json.dump({"lang": code}, f)


