# runtime accessor
_current_lang: str = DEFAULT_LANG
_listeners: list = []


def on_change(cb):
    if cb not in _listeners:
        _listeners.append(cb)


def remove_listener(cb):
    if cb in _listeners:
        _listeners.remove(cb)


def set_lang(code: str):
    global _current_lang
    if code in SUPPORTED and code != _current_lang:
        _current_lang = code
        save_lang(code)
        for cb in list(_listeners):
            try:
                cb()
            except Exception:
                pass


def init():
    global _current_lang
    _current_lang = load_lang()


def t(key: str, **kwargs) -> str:
    table = _STRINGS.get(key)
    if table is None:
        return key
    text = table.get(_current_lang) or table.get(DEFAULT_LANG) or key
    return text.format(**kwargs) if kwargs else text
